// Some portions generated by Codex

const { test, expect } = require('@playwright/test');
const { BLOCK_SIZE, TERM_VOLUME_LIMIT, compactRows, legacyRows, openStorageHarness, call, observe, physical, seedLegacy }
	= require('../query-block-storage-helper');

const BASE = (process.env.RDF4J_WORKBENCH_BASE_URL || 'http://127.0.0.1:8080/rdf4j-workbench').replace(/\/+$/, '');
let provenance;

test.beforeEach(async ({ page }) => {
	test.setTimeout(60000);
	provenance = await openStorageHarness(page, BASE);
});

test.afterEach(async ({ page }, testInfo) => {
	const cleanup = await page.evaluate(async () => window.__blockStorageHarness
		? window.__blockStorageHarness.shutdown() : { unavailable: true });
	await evidence(testInfo, 'owned-cleanup', cleanup);
	if (!cleanup.unavailable) {
		expect(cleanup.workerErrors).toEqual([]);
		expect(cleanup.failures).toEqual([]);
		expect(cleanup.remainingOwned).toEqual([]);
	}
});

async function evidence(testInfo, name, value) {
	await testInfo.attach(name, { body: Buffer.from(JSON.stringify({ provenance, ...value }, null, 2)),
		contentType: 'application/json' });
}

async function create(page) {
	const result = await call(page, 'create');
	expect(result.ok).toBe(true);
	expect(result.count).toBe(0);
	return result.storeId;
}

async function append(page, storeId, rows) {
	const result = await call(page, 'append', { storeId, rows });
	expect(result.ok).toBe(true);
	return result.count;
}

async function read(page, storeId, start, count) {
	const result = await call(page, 'read', { storeId, start, count });
	expect(result.ok).toBe(true);
	return result.rows;
}

function expectPacked(snapshot, logicalCount, ordinarySmallRows = true) {
	expect(snapshot.metadata.count).toBe(logicalCount);
	expect(snapshot.recordLengths.reduce((sum, count) => sum + count, 0)).toBe(logicalCount);
	let logicalStart = 0;
	for (let index = 0; index < snapshot.recordCount; index++) {
		expect(snapshot.keys[index]).toBe(logicalStart);
		expect(snapshot.recordLengths[index]).toBeGreaterThan(0);
		expect(snapshot.recordLengths[index]).toBeLessThanOrEqual(BLOCK_SIZE);
		if (snapshot.recordTextVolumes[index] > TERM_VOLUME_LIMIT) expect(snapshot.recordLengths[index]).toBe(1);
		logicalStart += snapshot.recordLengths[index];
	}
	if (ordinarySmallRows) {
		expect(snapshot.recordCount).toBe(Math.ceil(logicalCount / BLOCK_SIZE));
		expect(snapshot.recordLengths.slice(0, -1)).toEqual(Array(Math.max(0, snapshot.recordCount - 1)).fill(BLOCK_SIZE));
		if (logicalCount) expect(snapshot.recordLengths.at(-1)).toBe(logicalCount % BLOCK_SIZE || BLOCK_SIZE);
	}
	expect(snapshot.version).toBe(1);
	expect(snapshot.keyPaths).toEqual({ stores: 'id', rows: ['storeId', 'index'] });
}

test('native append uses bounded physical blocks and requests for arbitrary packets', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const rows = compactRows(BLOCK_SIZE * 4 + 1);
	await observe(page, true);
	expect(await append(page, storeId, rows)).toBe(rows.length);
	const stats = await observe(page);
	const snapshot = await physical(page, storeId);
	const result = await read(page, storeId, BLOCK_SIZE * 4 - 3, 10);
	await evidence(testInfo, 'append-block-complexity', { stats, snapshot, result });
	expect(result).toEqual(rows.slice(BLOCK_SIZE * 4 - 3));
	expect((stats.requests['rows.add'] || 0) + (stats.requests['rows.put'] || 0)).toBeLessThanOrEqual(Math.ceil(rows.length / BLOCK_SIZE));
	expectPacked(snapshot, rows.length);
});

test('lossless raw terms survive partial tail merges and serialized packet ordering', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const rows = compactRows(BLOCK_SIZE * 2 + 71, 0, true);
	const packets = [rows.slice(0, 32), rows.slice(32, 1056), [], rows.slice(1056)];
	const responses = await page.evaluate(({ storeId, packets }) => Promise.all(packets.map(rows =>
		window.__blockStorageHarness.send('append', { storeId, rows }))), { storeId, packets });
	expect(responses.every(response => response.ok)).toBe(true);
	expect(responses.map(response => response.count)).toEqual([32, 1056, 1056, rows.length]);
	const windows = [[0, 32], [1018, 22], [2044, 100], [rows.length, 10]];
	const results = [];
	for (const [start, count] of windows) {
		const actual = await read(page, storeId, start, count);
		expect(actual).toEqual(rows.slice(start, start + count));
		results.push({ start, count, returned: actual.length });
	}
	const snapshot = await physical(page, storeId);
	await evidence(testInfo, 'raw-term-tail-order', { results, snapshot, responses });
	expectPacked(snapshot, rows.length, false);
});

test('small late windows clone only intersecting blocks across boundaries and tails', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const rows = compactRows(BLOCK_SIZE * 6 + 3);
	await append(page, storeId, rows);
	const observations = [];
	for (const [start, count] of [[0, 1], [1020, 16], [2047, 5], [4094, 65], [6143, 20], [100000, 30]]) {
		await observe(page, true);
		const actual = await read(page, storeId, start, count);
		const stats = await observe(page);
		const end = Math.min(rows.length, start + count);
		const intersections = start >= end ? 0 : Math.floor((end - 1) / BLOCK_SIZE) - Math.floor(start / BLOCK_SIZE) + 1;
		observations.push({ start, count, returned: actual.length, intersections, stats });
		expect(actual).toEqual(rows.slice(start, start + count));
	}
	await evidence(testInfo, 'bounded-intersection-reads', { observations });
	for (const observation of observations) {
		expect(observation.stats.returnedPhysicalRecords).toBeLessThanOrEqual(observation.intersections);
		expect(observation.stats.returnedRecordWidths.every(width => width <= BLOCK_SIZE)).toBe(true);
	}
});

test('partial truncate then append keeps the committed prefix count and compact tail', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const rows = compactRows(BLOCK_SIZE * 2 + 257, 0, true);
	await append(page, storeId, rows);
	const truncated = await call(page, 'truncate', { storeId, count: BLOCK_SIZE + 1 });
	expect(truncated.ok).toBe(true);
	expect(truncated.count).toBe(BLOCK_SIZE + 1);
	const newRows = compactRows(67, rows.length, true);
	expect(await append(page, storeId, newRows)).toBe(BLOCK_SIZE + 68);
	const expected = rows.slice(0, BLOCK_SIZE + 1).concat(newRows);
	const actual = await read(page, storeId, 1000, 1000);
	const count = await call(page, 'count', { storeId });
	const snapshot = await physical(page, storeId);
	await evidence(testInfo, 'truncate-and-append-tail', { truncated, count, snapshot, returned: actual.length });
	expect(actual).toEqual(expected.slice(1000));
	expect(count.count).toBe(expected.length);
	expectPacked(snapshot, expected.length, false);
});

test('large and multibyte terms keep repeated append work bounded across variable blocks', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const labels = ['x'.repeat(43 * 1024), '漢'.repeat(Math.floor(43 * 1024 / 3)),
		'🙂'.repeat(Math.floor(43 * 1024 / 4)), 'مرحبا'.repeat(4400), 'y'.repeat(43 * 1024)];
	const rows = Array.from({ length: 40 }, (_unused, index) => [[0, `urn:large:${index}`],
		[2, labels[index % labels.length], 'urn:large:datatype']]);
	const observations = [];
	for (let start = 0; start < rows.length; start += 5) {
		await observe(page, true);
		expect(await append(page, storeId, rows.slice(start, start + 5))).toBe(start + 5);
		const stats = await observe(page);
		observations.push({ start, stats });
		expect(stats.returnedPhysicalRecords).toBeLessThanOrEqual(1);
		expect(stats.returnedRecordTextVolumes.every(volume => volume <= TERM_VOLUME_LIMIT)).toBe(true);
	}
	const snapshot = await physical(page, storeId);
	const actual = await read(page, storeId, 0, rows.length);
	await evidence(testInfo, 'large-variable-blocks', { snapshot, observations });
	expect(actual).toEqual(rows);
	expectPacked(snapshot, rows.length, false);
	expect(snapshot.recordTextVolumes.every(volume => volume <= TERM_VOLUME_LIMIT)).toBe(true);
	const windows = [];
	for (const [start, count] of [[1, 2], [17, 4], [35, 3], [rows.length, 10]]) {
		await observe(page, true);
		expect(await read(page, storeId, start, count)).toEqual(rows.slice(start, start + count));
		const stats = await observe(page);
		const end = Math.min(rows.length, start + count);
		const intersections = snapshot.keys.filter((key, index) => key < end
			&& key + snapshot.recordLengths[index] > start).length;
		windows.push({ start, count, intersections, stats });
		expect(stats.returnedPhysicalRecords).toBeLessThanOrEqual(intersections);
		expect(stats.returnedRecordTextVolumes.every(volume => volume <= TERM_VOLUME_LIMIT)).toBe(true);
	}
	await evidence(testInfo, 'large-variable-window-reads', { windows });
	const partialBlock = snapshot.recordLengths.findIndex((count, index) => index > 0 && count > 1);
	expect(partialBlock).toBeGreaterThan(0);
	const truncateCount = snapshot.keys[partialBlock] + 1;
	expect(truncateCount).toBeGreaterThan(1);
	expect((await call(page, 'truncate', { storeId, count: truncateCount })).ok).toBe(true);
	const tail = rows.slice(31, 38);
	expect(await append(page, storeId, tail)).toBe(truncateCount + tail.length);
	expect(await read(page, storeId, 0, rows.length)).toEqual(rows.slice(0, truncateCount).concat(tail));
	expectPacked(await physical(page, storeId), truncateCount + tail.length, false);
});

test('a single oversized row stays isolated and later packets never clone that tail', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const oversized = [[0, 'urn:oversized'], [2, '🙂'.repeat(128 * 1024), 'urn:oversized:datatype'],
		[2, '\u0000\u001f high:\ud800 low:\udc00', 'urn:lossless:control']];
	const prefix = compactRows(3);
	await append(page, storeId, prefix.concat([oversized]));
	await observe(page, true);
	const suffix = compactRows(17, 10000);
	expect(await append(page, storeId, suffix)).toBe(prefix.length + suffix.length + 1);
	const stats = await observe(page);
	const snapshot = await physical(page, storeId);
	const expected = prefix.concat([oversized], suffix);
	await evidence(testInfo, 'oversized-isolated-row', { snapshot, stats });
	expect(await read(page, storeId, 0, expected.length)).toEqual(expected);
	expect(stats.returnedPhysicalRecords).toBe(0);
	expectPacked(snapshot, expected.length, false);
	const oversizedBlocks = snapshot.recordTextVolumes.map((volume, index) => ({ volume, index }))
		.filter(block => block.volume > TERM_VOLUME_LIMIT);
	expect(oversizedBlocks).toHaveLength(1);
	expect(snapshot.recordLengths[oversizedBlocks[0].index]).toBe(1);
	expect((await call(page, 'truncate', { storeId, count: prefix.length })).ok).toBe(true);
	expect(await append(page, storeId, suffix)).toBe(prefix.length + suffix.length);
	expect(await read(page, storeId, 0, expected.length)).toEqual(prefix.concat(suffix));
});

test('invalid and growing truncates reject atomically and leave committed rows readable', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const rows = compactRows(1500);
	await append(page, storeId, rows);
	const before = await physical(page, storeId);
	const rejected = [];
	for (const count of [-1, 1.5, NaN, Number.MAX_SAFE_INTEGER + 1, rows.length + 1]) {
		const response = await call(page, 'truncate', { storeId, count });
		expect(response.ok).toBe(false);
		rejected.push({ count: String(count), response });
	}
	const after = await physical(page, storeId);
	const count = await call(page, 'count', { storeId });
	const actual = await read(page, storeId, 0, rows.length + 10);
	await evidence(testInfo, 'atomic-truncate-rejection', { before, after, count, rejected });
	expect(after).toEqual(before);
	expect(count.count).toBe(rows.length);
	expect(actual).toEqual(rows);
});

test('dispose range deletes only its owner without per-record cursor work', async ({ page }, testInfo) => {
	const owner = await create(page);
	const neighbour = await create(page);
	const neighbourRows = compactRows(7, 9000, true);
	const legacyId = `legacy-disposal-${testInfo.project.name}-${Date.now().toString(36)}`;
	const legacy = legacyRows(60);
	await append(page, owner, compactRows(BLOCK_SIZE * 3 + 1));
	await append(page, neighbour, neighbourRows);
	await seedLegacy(page, legacyId, legacy);
	await observe(page, true);
	const disposed = await call(page, 'dispose', { storeId: owner });
	expect(disposed.ok).toBe(true);
	const stats = await observe(page);
	const absent = await physical(page, owner);
	const retained = await read(page, neighbour, 0, 100);
	const legacyRetained = await read(page, legacyId, 0, 100);
	await evidence(testInfo, 'owned-range-disposal', { stats, absent, neighbourCount: retained.length, legacyCount: legacyRetained.length });
	expect(absent.metadata).toBeUndefined();
	expect(absent.recordCount).toBe(0);
	expect(retained).toEqual(neighbourRows);
	expect(legacyRetained).toEqual(legacy);
	expect(stats.cursorDeletes).toBe(0);
	expect(stats.cursorContinues).toBe(0);
	expect(stats.requests['rows.delete']).toBe(1);
	expect((await call(page, 'dispose', { storeId: owner })).ok).toBe(true);
});

test('legacy version-1 rows keep their format with another connection open', async ({ page }, testInfo) => {
	const storeId = `legacy-v1-${testInfo.project.name}-${Date.now().toString(36)}`;
	const original = legacyRows(1500);
	const initial = await seedLegacy(page, storeId, original);
	expect(initial.version).toBe(1);
	expect(initial.recordCount).toBe(original.length);
	expect(await read(page, storeId, 1020, 16)).toEqual(original.slice(1020, 1036));
	const extra = legacyRows(73, 1500);
	expect(await append(page, storeId, extra)).toBe(1573);
	const truncated = await call(page, 'truncate', { storeId, count: 1459 });
	expect(truncated.ok).toBe(true);
	const tail = legacyRows(17, 7000);
	expect(await append(page, storeId, tail)).toBe(1476);
	const expected = original.slice(0, 1459).concat(tail);
	expect(await read(page, storeId, 1448, 100)).toEqual(expected.slice(1448));
	const newStore = await create(page);
	await append(page, newStore, compactRows(1030));
	const legacySnapshot = await physical(page, storeId);
	const blockSnapshot = await physical(page, newStore);
	await evidence(testInfo, 'legacy-open-connection', { initial, legacySnapshot, blockSnapshot });
	expect(legacySnapshot.versionChanges).toBe(0);
	// The store keeps its legacy format; reading it only stamps when it was last used, for the sweep of stores
	// abandoned without a pagehide.
	expect(legacySnapshot.metadata).toEqual({ id: storeId, count: expected.length, touched: expect.any(Number) });
	expect(legacySnapshot.recordCount).toBe(expected.length);
	expect(legacySnapshot.recordLengths).toEqual(Array(expected.length).fill(4));
	expectPacked(blockSnapshot, 1030);
});

test('zero and exact-boundary truncates can append again without phantom tail rows', async ({ page }, testInfo) => {
	const storeId = await create(page);
	const rows = compactRows(BLOCK_SIZE * 2 + 1);
	await append(page, storeId, rows);
	for (const count of [BLOCK_SIZE * 2, BLOCK_SIZE, 0]) {
		const result = await call(page, 'truncate', { storeId, count });
		expect(result.ok).toBe(true);
		expect(await read(page, storeId, Math.max(0, count - 2), 10)).toEqual(rows.slice(Math.max(0, count - 2), count));
	}
	const replacement = compactRows(BLOCK_SIZE + 3, 5000);
	expect(await append(page, storeId, replacement)).toBe(replacement.length);
	expect(await read(page, storeId, 0, replacement.length + 1)).toEqual(replacement);
	const snapshot = await physical(page, storeId);
	await evidence(testInfo, 'zero-boundary-reappend', { snapshot });
	expectPacked(snapshot, replacement.length);
});
